quota_scripts.script:
// 复活条件：/alpha 内部接口官方无稳定承诺，失效时对照 CLI 新版本核对端点（npm command-code dist/cli.mjs fetchUsageData）。
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function intVal(v) {
  return typeof v === "number" && Number.isInteger(v) ? v : null;
}
function msToIso(ms) {
  try {
    var iso = new Date(ms).toISOString();
  } catch (e) {
    return null;
  }
  if (ms % 1000 === 0) return iso.slice(0, 19) + "+00:00";
  return iso.slice(0, 23) + "+00:00";
}
function numField(obj, f, d) {
  if (obj == null) return d;
  var v = obj[f];
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return d;
}
function numOrNull(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return null;
}
var BASE = "https://api.commandcode.ai";
var H = { "Authorization": "Bearer " + ctx.apiKey, "Content-Type": "application/json" };
function get(path) { return http.get(BASE + path, H); }
var who;
try {
  who = get("/alpha/whoami?limits=1");
} catch (e) {
  return { success: false, error: httpErr(e) };
}
var orgId = who != null && who.org != null && typeof who.org.id === "string" ? who.org.id : null;
function orgQ(extra) {
  var p = [];
  if (orgId !== null) p.push("orgId=" + encodeURIComponent(orgId));
  if (extra) p.push(extra);
  return p.length ? "?" + p.join("&") : "";
}
var credits, subs;
try {
  credits = get("/alpha/billing/credits" + orgQ());
  subs = get("/alpha/billing/subscriptions" + orgQ());
} catch (e) {
  return { success: false, error: httpErr(e) };
}
var subData = subs != null && typeof subs.data === "object" && !Array.isArray(subs.data) ? subs.data : {};
var since = typeof subData.currentPeriodStart === "string" && subData.currentPeriodStart !== "" ? subData.currentPeriodStart : null;
var summaryPath = "/alpha/usage/summary" + orgQ(since !== null ? "since=" + encodeURIComponent(since) : null);
var summary;
try {
  summary = get(summaryPath);
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (summary == null || typeof summary !== "object" || Array.isArray(summary)) summary = {};
var cr = credits != null && typeof credits.credits === "object" && !Array.isArray(credits.credits) ? credits.credits : {};
var wl = typeof credits.windowLimits === "object" && !Array.isArray(credits.windowLimits) ? credits.windowLimits : {};
function windowTier(name, src) {
  if (src == null || typeof src !== "object" || Array.isArray(src)) return null;
  var cap = numField(src, "cap", 0.0);
  var used = numField(src, "used", 0.0);
  var remaining = Math.max(cap - used, 0.0);
  var utilization = cap > 0.0 ? (used / cap) * 100.0 : 0.0;
  var rt = intVal(src.resetAt);
  return { name: name, utilization: utilization, resets_at: rt === null ? null : msToIso(rt), limit: cap, remaining: remaining, unit: "prompt_count" };
}
var tiers = [];
var five = windowTier("five_hour", wl.fiveHour);
if (five !== null) tiers.push(five);
var weekly = windowTier("weekly_limit", wl.weekly);
if (weekly !== null) tiers.push(weekly);
var mc = numOrNull(cr.monthlyCredits);
var tc = numOrNull(summary.totalCost);
if (mc !== null && mc > 0.0 && tc !== null) {
  var rt = intVal(subData.currentPeriodEnd);
  tiers.push({ name: "monthly", utilization: (tc / mc) * 100.0, resets_at: rt !== null ? msToIso(rt) : (typeof subData.currentPeriodEnd === "string" && subData.currentPeriodEnd !== "" ? subData.currentPeriodEnd : null), limit: mc, remaining: Math.max(mc - tc, 0.0), unit: "prompt_count" });
}
var remaining = numField(cr, "monthlyCredits", 0.0) + numField(cr, "purchasedCredits", 0.0) + numField(cr, "freeCredits", 0.0);
var used = numField(summary, "totalCost", 0.0);
return {
  success: true,
  error: null,
  balance: { remaining: remaining, total: remaining + used, used: used, currency: "USD", is_valid: true },
  coding_plan: { level: typeof subData.planId === "string" && subData.planId !== "" ? subData.planId : null, tiers: tiers }
};
